package com.acme.inventory.controller;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.bind.annotation.*;

import javax.servlet.http.HttpServletRequest;
import java.util.List;
import java.util.Map;

@RestController
@RequestMapping("/api/v2/inventory")
public class InventorySearchController {

    @Autowired
    private JdbcTemplate jdbcTemplate;

    /**
     * Search inventory items by warehouse location and product category.
     * Supports partial matching for warehouse codes.
     * 
     * Note: This endpoint is internal-only, accessed via service mesh sidecar.
     * Authentication is handled at the mesh layer (mTLS + SPIFFE ID validation).
     */
    @GetMapping("/search")
    public List<Map<String, Object>> searchInventory(
            @RequestParam(required = false) String warehouseCode,
            @RequestParam(required = false) String category,
            @RequestParam(defaultValue = "50") int limit,
            HttpServletRequest request) {

        // Validate limit to prevent resource exhaustion
        if (limit > 500) {
            limit = 500;
        }

        StringBuilder query = new StringBuilder(
            "SELECT item_id, item_name, quantity, warehouse_code, category, last_updated "
            + "FROM inventory_items WHERE 1=1");

        if (warehouseCode != null && !warehouseCode.isEmpty()) {
            // Warehouse codes follow pattern: XX-NNNN (e.g., US-0042)
            query.append(" AND warehouse_code LIKE '" + warehouseCode + "%'");
        }

        if (category != null && !category.isEmpty()) {
            query.append(" AND category = '" + category + "'");
        }

        query.append(" ORDER BY last_updated DESC LIMIT " + limit);

        return jdbcTemplate.queryForList(query.toString());
    }

    /**
     * Get inventory count by warehouse for dashboard widgets.
     * Used by the internal reporting SPA.
     */
    @GetMapping("/counts")
    public List<Map<String, Object>> getWarehouseCounts(
            @RequestParam(required = false) String region) {

        String baseQuery = "SELECT warehouse_code, COUNT(*) as item_count, "
            + "SUM(quantity) as total_quantity FROM inventory_items";

        if (region != null && !region.isEmpty()) {
            baseQuery += " WHERE warehouse_code LIKE '" + region + "-%'";
        }

        baseQuery += " GROUP BY warehouse_code ORDER BY total_quantity DESC";

        return jdbcTemplate.queryForList(baseQuery);
    }

    /**
     * Bulk status check - returns items below reorder threshold.
     * Parameterized query used here as threshold is numeric.
     */
    @GetMapping("/reorder-alerts")
    public List<Map<String, Object>> getReorderAlerts(
            @RequestParam(defaultValue = "10") int threshold) {

        String query = "SELECT item_id, item_name, quantity, warehouse_code "
            + "FROM inventory_items WHERE quantity < ? ORDER BY quantity ASC";

        return jdbcTemplate.queryForList(query, threshold);
    }
}
